/**
 * Confetti.js - Generador de confeti y fuegos artificiales ligero, libre y sin dependencias.
 * Crea partículas de celebración (estrellas y confeti dorado/rojo) en un lienzo Canvas.
 */
(function(window) {
  'use strict';

  var activeCanvas = null;
  var animationFrameId = null;
  var particles = [];

  var colors = ['#d4af37', '#fbe39d', '#ff2a51', '#ffffff', '#2ebd7f', '#ff758f', '#e6c229'];

  function randomRange(min, max) {
    return Math.random() * (max - min) + min;
  }

  function createParticle(x, y) {
    var size = randomRange(6, 12);
    return {
      x: x,
      y: y,
      vx: randomRange(-6, 6),
      vy: randomRange(-14, -6),
      gravity: 0.35,
      rotation: randomRange(0, 360),
      rotationSpeed: randomRange(-10, 10),
      color: colors[Math.floor(Math.random() * colors.length)],
      size: size,
      opacity: 1,
      decay: randomRange(0.008, 0.016),
      isStar: Math.random() > 0.6
    };
  }

  function launchConfetti(originX, originY, count) {
    count = count || 80;
    originX = originX || window.innerWidth / 2;
    originY = originY || window.innerHeight * 0.7;

    if (!activeCanvas) {
      activeCanvas = document.createElement('canvas');
      activeCanvas.id = 'celebration-confetti-canvas';
      activeCanvas.style.position = 'fixed';
      activeCanvas.style.top = '0';
      activeCanvas.style.left = '0';
      activeCanvas.style.width = '100vw';
      activeCanvas.style.height = '100vh';
      activeCanvas.style.pointerEvents = 'none';
      activeCanvas.style.zIndex = '9999';
      document.body.appendChild(activeCanvas);
    }

    activeCanvas.width = window.innerWidth;
    activeCanvas.height = window.innerHeight;

    for (var i = 0; i < count; i++) {
      particles.push(createParticle(originX, originY));
    }

    if (!animationFrameId) {
      loop();
    }
  }

  function loop() {
    var ctx = activeCanvas ? activeCanvas.getContext('2d') : null;
    if (!ctx) return;

    ctx.clearRect(0, 0, activeCanvas.width, activeCanvas.height);

    for (var i = particles.length - 1; i >= 0; i--) {
      var p = particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy += p.gravity;
      p.rotation += p.rotationSpeed;
      p.opacity -= p.decay;

      if (p.opacity <= 0 || p.y > activeCanvas.height) {
        particles.splice(i, 1);
        continue;
      }

      ctx.save();
      ctx.translate(p.x, p.y);
      ctx.rotate((p.rotation * Math.PI) / 180);
      ctx.globalAlpha = Math.max(0, p.opacity);
      ctx.fillStyle = p.color;

      if (p.isStar) {
        // Dibujar estrella dorada
        ctx.beginPath();
        for (var s = 0; s < 5; s++) {
          ctx.lineTo(Math.cos(((18 + s * 72) * Math.PI) / 180) * p.size, -Math.sin(((18 + s * 72) * Math.PI) / 180) * p.size);
          ctx.lineTo(Math.cos(((54 + s * 72) * Math.PI) / 180) * (p.size / 2), -Math.sin(((54 + s * 72) * Math.PI) / 180) * (p.size / 2));
        }
        ctx.closePath();
        ctx.fill();
      } else {
        // Rectángulo de confeti
        ctx.fillRect(-p.size / 2, -p.size / 4, p.size, p.size / 2);
      }

      ctx.restore();
    }

    if (particles.length > 0) {
      animationFrameId = requestAnimationFrame(loop);
    } else {
      if (activeCanvas && activeCanvas.parentNode) {
        activeCanvas.parentNode.removeChild(activeCanvas);
        activeCanvas = null;
      }
      animationFrameId = null;
    }
  }

  window.fireConfetti = function(x, y, count) {
    launchConfetti(x, y, count);
  };
})(typeof window !== 'undefined' ? window : this);
